export function showSupportChoices({modal,close,pay,contact}){modal(`<div class="eyebrow">A LITTLE HELP GOES A LONG WAY</div><h2>Bạn muốn giúp theo cách nào?</h2><p>Chọn hỗ trợ ngay hoặc liên hệ chủ thẻ để tìm hiểu thêm.</p><div class="support-choice-list"><button id="card-choice-pay"><span>♡</span><div><strong>Gửi tiền giúp qua app</strong><small>Thanh toán trong ứng dụng · Sẽ được bổ sung sau</small></div><b>→</b></button><button id="card-choice-contact"><span>✉</span><div><strong>Gửi thông báo & nhắn tin</strong><small>Hỏi chủ thẻ để có thêm thông tin đầy đủ</small></div><b>→</b></button></div><p class="support-choice-note">Bản xây dựng: chưa có thanh toán, gửi thông báo hoặc tin nhắn đến người thật.</p>`);document.querySelector('#card-choice-pay').onclick=()=>{close();pay();};document.querySelector('#card-choice-contact').onclick=()=>{close();contact();};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showSupportMessageStep({id,name,modal,toast}){let draft='';try{draft=JSON.parse(localStorage.getItem('debtfreelately-support-message-drafts')||'{}')[id]?.message||'';}catch{}
modal(`<div class="eyebrow">A LITTLE KINDNESS, IN YOUR WORDS</div><h2>Một lời nhắn để tiếp thêm hy vọng.</h2><p>Phần lời nhắn ở cuối luồng hỗ trợ. Sau khi có thanh toán thật, lời nhắn sẽ đi cùng tên và số tiền người giúp trên Wall of Gratitude.</p><div class="info-box">Bản xây dựng: thanh toán chưa được tích hợp. Lưu bên dưới chỉ tạo bản nháp trên thiết bị, chưa gửi lời nhắn hoặc chuyển tiền.</div><form id="support-message-form"><label for="support-message">hãy gửi cho <strong>${esc(name)}</strong> một lời khuyên hoặc một lời chúc ngắn</label><textarea id="support-message" name="message" maxlength="200" placeholder="Ví dụ: Từng bước một nhé, chúc bạn sớm có một khởi đầu mới!">${esc(draft)}</textarea><div class="support-message-meta"><span>Không bắt buộc · Tối đa 200 ký tự</span><span id="support-message-count">${draft.length}/200</span></div><p class="support-message-hint">Một lời động viên nhỏ cũng có thể tạo nên khác biệt lớn.</p><p id="support-message-status" class="form-error" role="status"></p><button class="dark">Lưu lời nhắn nháp</button></form>`);
document.querySelector('#support-message').oninput=event=>document.querySelector('#support-message-count').textContent=event.target.value.length+'/200';document.querySelector('#support-message-form').onsubmit=event=>{event.preventDefault();const message=new FormData(event.target).get('message').trim();try{const key='debtfreelately-support-message-drafts',items=JSON.parse(localStorage.getItem(key)||'{}');items[id]={recipient:name,message,updatedAt:new Date().toISOString(),status:'draft'};localStorage.setItem(key,JSON.stringify(items));document.querySelector('#support-message-status').textContent='Đã lưu bản nháp trên thiết bị. Chưa gửi lời nhắn hoặc chuyển tiền.';toast('Đã lưu lời nhắn nháp.');}catch{document.querySelector('#support-message-status').textContent='Không lưu được bản nháp. Vui lòng thử lại.';}};
}
